import { Avatar, type AvatarSize } from '@absoluteui/components/avatar';

const row = document.createElement('p');
document.body.append(row);
const people: [string, AvatarSize][] = [['Ada Lovelace', 'xs'], ['Grace Hopper', 'sm'], ['Alan Turing', 'md'], ['Barbara Liskov', 'lg'], ['Edsger Dijkstra', 'xl']];
for (const [name, size] of people) {
  const host = document.createElement('span');
  row.append(host, ' ');
  Avatar.create(host, { name, size, status: size === 'md' ? 'online' : null });
}
const team = document.createElement('span');
row.append(team);
Avatar.create(team, { name: 'Platform team', shape: 'square', status: 'busy' });

import { Avatar } from '@absoluteui/components/avatar';

const author = document.createElement('p');
const picture = document.createElement('span');
author.append(picture, ' Grace Hopper commented');
document.body.append(author);
// The name is printed next to the avatar, so the avatar is not announced again.
Avatar.create(picture, { name: 'Grace Hopper', size: 'sm', decorative: true });
